Here is the original GNU C++14 code you have to rewrite:
<original_code>
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
struct networkflow{
    struct node{
        int v, w, rev;
    };
    void setEdge(int u, int v, int fl){
        int sz1= (int)adj[v].size();
        int sz2 = (int)adj[u].size();
        adj[u].push_back({v, fl, sz1});
        adj[v].push_back({u, 0, sz2});
    }
    vector<vector<node> > adj;
    vector<int> lev, edge_tried;
    int st, ed;
    networkflow(int V, int s, int t): adj(V), lev(V), edge_tried(V), st(s), ed(t){}
    bool assign_level(){
        fill(lev.begin(), lev.end(), -1);
        lev[st]=0;
        queue<int>que;que.push(st);
        while(!que.empty()){
            int now =que.front();que.pop();
            for(int i=0; i<adj[now].size(); i++){
                int nxt = adj[now][i].v;
                if(lev[nxt]==-1 && adj[now][i].w!=0){
                    lev[nxt] =  lev[now]+1;
                    que.push(nxt);
                }
            }
        }
        return (lev[ed]!=-1);
    }
    int dfs(int now, int fl){
        if(now==ed)return fl;
        for(int &i=edge_tried[now]; i<adj[now].size(); i++){
            int nxt = adj[now][i].v;
            if(lev[nxt]==lev[now]+1 && adj[now][i].w!=0){
                int nxtflow = dfs(nxt, min(fl, adj[now][i].w));
                if(nxtflow){
                    adj[now][i].w-=nxtflow;
                    adj[nxt][adj[now][i].rev].w+=nxtflow;
                    return nxtflow;
                }
            }
        }
        return 0;
    }
    ll dinic(){
        ll ret=0;
        while(assign_level()){
            fill(edge_tried.begin(), edge_tried.end(), 0);
            while(1){
                int amt = dfs(st, 2e9);
                if(amt==0)break;
                ret+=amt;
            }
        }
        return ret;
    }
};

int n, ti, ck[15][15];
string str[15], es[15];
int yy, xx;
int dy[]={1, -1, 0, 0};
int dx[]={0, 0, 1, -1};
void go()
{
    queue<pair<int, int> >que;que.push({yy, xx});
    ck[yy][xx]=1;
    int lev=1;
    while(!que.empty()){
        int sz = (int)que.size();
        for(int ite=0; ite<sz; ite++){
        pair<int, int> now = que.front();que.pop();
        for(int i=0; i<4; i++){
            int ny = now.first + dy[i];
            int nx = now.second + dx[i];
            if(!(ny>=0 && ny<n &&nx>=0 && nx<n))continue;
            if(ck[ny][nx] || str[ny][nx]=='Y')continue;
            ck[ny][nx] = lev;
            que.push({ny, nx});
        }
        }
        ++lev;
        lev=min(lev, ti);
    }
}
int table[15][15][65];
int main()
{
    cin>>n>>ti;
    for(int i=0; i<n; i++){
        cin>>str[i];
        for(int j=0 ;j<n; j++){
            if(str[i][j] =='Z'){
                    yy=i, xx=j;
            }
        }
    }
    getline(cin, str[n]);
    getline(cin, str[n]);

    for(int i=0; i<n; i++){
        cin>>es[i];
    }
    go();
    int nodecnt=0;

    for(int i=0; i<n; i++){
        for(int j=0 ;j<n; j++){
            if('0'<=str[i][j] &&str[i][j]<='9'){
                if(ck[i][j]==0)ck[i][j] = ti;
                for(int t =0; t<ck[i][j]; t++){
                    table[i][j][t]=++nodecnt;
                }
            }
            if('1'<=es[i][j] && es[i][j] <='9'){
                table[i][j][ck[i][j]]=++nodecnt;
            }
        }
    }


    int INF = (int)1e9;
    int st= 0, ed = nodecnt+3;
    networkflow net(nodecnt+5, st, ed);
    for(int i=0; i<n; i++){
        for(int j=0 ;j<n; j++){
             if('1'<=str[i][j] &&str[i][j]<='9'){
                    net.setEdge(st, table[i][j][0], str[i][j]-'0');
             }

             for(int ite=0; ite<4; ite++){
                int ny = i + dy[ite];
                int nx = j + dx[ite];
                if(!(ny>=0 && ny<n &&nx>=0 &&nx<n))continue;
                if(str[ny][nx]=='Y' || str[ny][nx]=='Z')continue;
                for(int t=0; ; t++){
                    if(table[i][j][t]==0)break;
                    if(t==ck[i][j] && es[i][j]>='1' && es[i][j]<='9')break;///마지막골인 가능하지만 뿌려선 안됨
                    if(table[ny][nx][t+1]){
                        net.setEdge(table[i][j][t], table[ny][nx][t+1], INF);
                    }
                }
             }

            if('1'<=es[i][j] &&es[i][j]<='9'){
                for(int t = 0; t<ck[i][j]; t++){
                    net.setEdge(table[i][j][t], table[i][j][t+1], INF);
                }
                net.setEdge(table[i][j][ck[i][j]], ed, es[i][j]-'0');
            }
        }
    }
    int ans = net.dinic();
    cout<<ans<<endl;

}

